if(b.type==='house'){html+=`<p>Работают: ${(b.workerJobs||[]).length} / ${Math.floor(b.residents*.5)} жителей трудоспособного возраста.</p>`;const labels={road:'Связь с ратушей',water:'Чистая вода',food:'Еда с рынка',pots:'Посуда',beauty:'Красота района'};html+=Object.entries(b.needs).map(([n,ok])=>`<div class="need"><span>${labels[n]}</span><span class="${ok?'yes':'no'}">${ok?'Есть':'Нужно'}</span></div>`).join('');html+=`<p>${!b.connected?'Проложите дорогу от дома к ратуше.':b.level===3?'Жители довольны своим районом.':!b.needs.water?'Нужен колодец на этой дорожной сети, не дальше 8 клеток.':!b.needs.food?'Нужен работающий рынок и запас еды.':b.level===2&&!b.needs.pots?'Постройте гончарную и обеспечьте её работниками.':b.level===2&&!b.needs.beauty?'Посадите дерево в пределах 3 клеток.':'Дом готов к росту. Поддерживайте снабжение два цикла.'}</p>`;}
else if(b.type==='hall'){html+=`<p>Занято ${city.employed} из ${city.workforce} работников.<br>Без работы: ${city.unemployed}. Свободных мест: ${city.vacancies}.<br>Посуда на складе: ${Math.floor(city.pots)}.<br>${b.workers?'Ратуша собирает доход. Торговля доступна через порт.':'Нет работника: сбор дохода приостановлен.'}<br>Работники ратуши: ${b.workers}/${city.capacity(b)}.</p>`;}
else{html+=`<p>${TYPES[b.type].desc}<br>${['tree','palisade'].includes(b.type)?'':b.connected?'Соединено с ратушей.':'Нет дороги к ратуше.'}${TYPES[b.type].jobs?'<br>Работники: '+b.workers+'/'+city.capacity(b):''}${b.type==='well'||b.type==='market'?'<br>Обслуживает домов: '+(city.serviceLoad.get(b.id)||0):''}</p>`;}
