const cargo=this.textures.get('cargo'),ci=cargo.getSourceImage();for(let i=0;i<6;i++){const col=i%3,row=Math.floor(i/3),x=Math.round(col*ci.width/3),y=Math.round(row*ci.height/2);cargo.add('cart'+i,0,x,y,Math.round((col+1)*ci.width/3)-x,Math.round((row+1)*ci.height/2)-y);}
