animateForest(){for(const tree of city.forestNodes){let sprite=this.forestSprites.get(tree.id);if(!sprite){sprite=this.add.image(tree.x*TILE+32,tree.y*TILE+37,'atlas',tree.type==='broadleaf'?'sprite10':'sprite11').setOrigin(.5,.8).setDepth(3);this.forestSprites.set(tree.id,sprite);}const grow=tree.alive?1:Math.max(0,(city.time-(tree.respawnAt-120))/120),sapling=!tree.alive&&grow>.45;const texture=tree.alive||sapling?'atlas':'loggers',frame=tree.alive||sapling?(tree.type==='broadleaf'?'sprite10':'sprite11'):'sprite3';sprite.setTexture(texture,frame).setVisible(!city.at(tree.x,tree.y));if(tree.alive||sapling){const scale=tree.alive?1:(grow-.45)/.55*.8+.2;sprite.setDisplaySize(83*scale,92*scale);}else sprite.setDisplaySize(38,38);}const live=new Set();for(const w of city.lumberjacks){live.add(w.id);let sprite=this.loggerSprites.get(w.id);if(!sprite){sprite=this.add.image(0,0,'loggers','sprite0').setDisplaySize(34,34).setOrigin(.5,.85);this.loggerSprites.set(w.id,sprite);}const lodge=city.buildings.find(b=>b.id===w.lodgeId),active=lodge?.connected&&lodge.workers>w.slot;sprite.setTexture('loggers',w.cargo?'sprite1':w.state==='hunt'?'sprite2':'sprite0').setVisible(w.state!=='idle').setPosition(w.x*TILE+32,w.y*TILE+43+(active?Math.sin(city.time*10+w.slot)*1.4:0)).setDepth(18+w.y*10).setRotation(w.state==='hunt'&&active?Math.sin(city.time*7)*.14:0);}for(const[id,sprite]of this.loggerSprites)if(!live.has(id)){sprite.destroy();this.loggerSprites.delete(id);}}
animateServices(){const damaged=new Set();for(const b of city.buildings){if(b.type==='tree'||b.fire||b.hp/b.maxHp>.8||city.time-(b.lastInspection??city.time)<=90)continue;damaged.add(b.id);let sprite=this.damageSprites.get(b.id);if(!sprite){sprite=this.add.image(0,0,'engineers','sprite3').setDisplaySize(27,27);this.damageSprites.set(b.id,sprite);}sprite.setPosition(b.x*TILE+49,b.y*TILE+48).setDepth(19+b.y*10);}for(const[id,sprite]of this.damageSprites)if(!damaged.has(id)){sprite.destroy();this.damageSprites.delete(id);}if(!this.serviceFX)this.serviceFX=this.add.graphics().setDepth(1800);this.serviceFX.clear();const fires=new Set();for(const b of city.buildings.filter(b=>b.fire)){fires.add(b.id);let sprite=this.fireSprites.get(b.id);if(!sprite){sprite=this.add.image(0,0,'fire','sprite3').setOrigin(.5,.85);this.fireSprites.set(b.id,sprite);}const flicker=Math.sin(city.time*9+b.id);sprite.setPosition(b.x*TILE+32,b.y*TILE+34).setDisplaySize(72+flicker*5,78+flicker*7).setDepth(14+b.y*10);for(let i=0;i<3;i++){const p=(city.time*.4+i/3)%1;this.serviceFX.fillStyle(0x5b5740,(1-p)*.28);this.serviceFX.fillCircle(b.x*TILE+32+Math.sin(p*5)*9,b.y*TILE-5-p*48,5+p*10);}}for(const[id,sprite]of this.fireSprites)if(!fires.has(id)){sprite.destroy();this.fireSprites.delete(id);}const live=new Set();for(const [kind,workers]of [['fire',city.firefighters],['engineers',city.engineers]])for(const w of workers){live.add(w.id);let sprite=this.serviceSprites.get(w.id);if(!sprite){sprite=this.add.image(0,0,kind,'sprite1').setOrigin(.5,.85).setDisplaySize(34,34);this.serviceSprites.set(w.id,sprite);}const station=city.buildings.find(b=>b.id===w.stationId),active=station?.connected&&!station.fire&&station.workers>w.slot;const frame=kind==='fire'?(w.water>0?2:1):(w.state==='repair'?2:1);sprite.setTexture(kind,'sprite'+frame).setVisible(w.state!=='idle').setPosition(w.x*TILE+32,w.y*TILE+43+(active?Math.sin(city.time*10+w.slot)*1.5:0)).setDepth(18+w.y*10).setRotation(w.state==='repair'&&active?Math.sin(city.time*8)*.12:0);if(kind==='fire'&&w.state==='extinguish'&&active&&w.water>0){const target=city.buildings.find(b=>b.id===w.targetId&&b.fire);if(target){this.serviceFX.lineStyle(3,0x9dd4ca,.8);this.serviceFX.lineBetween(w.x*TILE+37,w.y*TILE+21,target.x*TILE+32,target.y*TILE+13);this.serviceFX.fillStyle(0xc3e5d7,.7);this.serviceFX.fillCircle(target.x*TILE+32+Math.sin(city.time*12)*5,target.y*TILE+13,3);}}}for(const[id,sprite]of this.serviceSprites)if(!live.has(id)){sprite.destroy();this.serviceSprites.delete(id);}}
